import"chrome://resources/cr_elements/cr_tab_box/cr_tab_box.js";import{assert}from"chrome://resources/js/assert.js";import{addWebUiListener,sendWithPromise}from"chrome://resources/js/cr.js";import{createElementFromText}from"./utils.js";function refreshServiceStatus(){sendWithPromise("getServiceStatus").then(onGetServiceStatus)}function onGetServiceStatus(statusString){const serviceStatus=document.querySelector("#service-status");assert(serviceStatus);serviceStatus.textContent=statusString}function refreshNotificationSource(){sendWithPromise("getNotificationSource").then(onGetNotificationSource)}function onGetNotificationSource(sourceString){const notificationSource=document.querySelector("#notification-source");assert(notificationSource);notificationSource.textContent=sourceString}let lastLogEventId=-1;function refreshLog(){sendWithPromise("getLog",lastLogEventId).then(onGetLog)}function clearLogs(){chrome.send("clearLogs");const logEntries=document.querySelector("#log-entries");assert(logEntries);assert(window.trustedTypes);logEntries.innerHTML=window.trustedTypes.emptyHTML}function onGetLog(logEntries){const itemContainer=document.querySelector("#log-entries");assert(itemContainer);for(let i=0;i<logEntries.length;i++){const logEntry=logEntries[i];const tr=document.createElement("tr");const error=/ERROR/.test(logEntry.logEvent)?" error":"";tr.appendChild(createElementFromText("td",logEntry.time,{class:"log-time"}));tr.appendChild(createElementFromText("td",logEntry.logEvent,{class:"log-event"+error}));itemContainer.appendChild(tr);lastLogEventId=logEntry.id}}function main(){const tabBox=document.querySelector("cr-tab-box");assert(tabBox);tabBox.hidden=false;const clearButton=document.querySelector("#clear-log-button");assert(clearButton);clearButton.addEventListener("click",clearLogs);refreshServiceStatus();refreshNotificationSource();addWebUiListener("service-status-changed",onGetServiceStatus);window.setInterval(refreshLog,1e3)}document.addEventListener("DOMContentLoaded",main);